import (
	"fmt"
	"sort"
)

func main() {
	basket := map[string]int{"pear": 3, "apple": 5, "fig": 1}

	total := 0
	for _, n := range basket {
		total += n
	}
	fmt.Println("total:", total)

	keys := make([]string, 0, len(basket))
	for k := range basket {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		fmt.Printf("%s: %d\n", k, basket[k])
	}
}

