package main

import (
	"fmt"
	"sort"
)

func main() {
	rooms := map[int]string{204: "Lab", 101: "Office", 150: "Library"}

	firstFloor := 0
	for num := range rooms {
		if num < 200 {
			firstFloor++
		}
	}
	fmt.Println("floor 1 rooms:", firstFloor)

	nums := make([]int, 0, len(rooms))
	for num := range rooms {
		nums = append(nums, num)
	}
	sort.Ints(nums)
	for _, num := range nums {
		fmt.Printf("%d: %s\n", num, rooms[num])
	}
}

