package main

import (
	"fmt"
	"sort"
	"strings"
)

func main() {
	counts := make(map[string]int)
	for _, c := range strings.Fields("red blue red green blue red") {
		counts[c]++
	}
	colors := make([]string, 0, len(counts))
	for c := range counts {
		colors = append(colors, c)
	}
	sort.Strings(colors)
	for _, c := range colors {
		fmt.Println(c, counts[c])
	}

	byLen := make(map[int][]string)
	for _, w := range []string{"cat", "horse", "dog", "mouse", "ox"} {
		byLen[len(w)] = append(byLen[len(w)], w)
	}
	lengths := make([]int, 0, len(byLen))
	for n := range byLen {
		lengths = append(lengths, n)
	}
	sort.Ints(lengths)
	for _, n := range lengths {
		fmt.Printf("%d: %v\n", n, byLen[n])
	}
}

