package main

import (
	"fmt"
	"sort"
	"strings"
)

func main() {
	ballots := "ana bo ana cy bo ana"
	names := []string{"ana", "bo", "al", "cy", "bea"}

	votes := make(map[string]int)
	for _, v := range strings.Fields(ballots) {
		votes[v]++
	}
	candidates := make([]string, 0, len(votes))
	for c := range votes {
		candidates = append(candidates, c)
	}
	sort.Strings(candidates)
	for _, c := range candidates {
		fmt.Println(c, votes[c])
	}

	byLetter := make(map[string][]string)
	for _, name := range names {
		first := string(name[0])
		byLetter[first] = append(byLetter[first], name)
	}
	letters := make([]string, 0, len(byLetter))
	for l := range byLetter {
		letters = append(letters, l)
	}
	sort.Strings(letters)
	for _, l := range letters {
		fmt.Printf("%s: %v\n", l, byLetter[l])
	}
}
